  on('GET', '/api/mbot/meetings', ({ u, q }) => { need(u, 'mbot'); const g = k => (q && q.get && q.get(k)) || '', s = g('q').toLowerCase(); return MT.meetings.filter(m => inMeet(u, m)).filter(m => (g('scope') === 'organized' ? m.organizerId === u.id : g('scope') === 'participated' ? m.organizerId !== u.id : true) && (!g('transcript') || (!m.removed && !m.summaryOff)) && (!g('focus') || isFocus(u, m)) && (!g('from') || m.at.slice(0, 10) >= g('from')) && (!g('to') || m.at.slice(0, 10) <= g('to')) && (!s || [m.title, ...m.participants.map(p => p.email), m.summary.overall, ...m.summary.points, ...m.actions.map(a => a.task)].join(' ').toLowerCase().includes(s))).map(m => mRow(u, m)); });
  on('GET', '/api/mbot/meetings/:id', ({ u, p }) => { need(u, 'mbot'); const m = meet(u, p.id), gone = m.removed || m.summaryOff; return { ...mRow(u, m), editRights: m.editRights, people: m.participants.map(x => ({ ...x, focus: focusOf(u).some(f => f.email.toLowerCase() === x.email.toLowerCase()), host: !!x.userId && x.userId === m.organizerId })), summary: gone ? null : m.summary, transcript: gone ? [] : m.transcript, actions: gone ? [] : m.actions.map(a => actView(u, m, a)), notes: m.notes[u.id] || [], domain: domain(u) }; });
