  const EC = R.echo;
  const HINDI = [[1, 'नमस्ते, सब लोग जुड़ गए हैं तो शुरू करते हैं।'], [1, 'आज हमें पिछले हफ्ते की डिलीवरी और अगले महीने के ऑर्डर पर बात करनी है।'], [2, 'पिछले हफ्ते बारह में से ग्यारह ऑर्डर समय पर पहुँचे।'], [2, 'एक ऑर्डर टेस्ट सर्टिफिकेट न होने की वजह से रुका था।'], [3, 'भुगतान की तरफ से दो इनवॉइस रुके हुए हैं, क्योंकि कुल रकम परचेज़ ऑर्डर से मेल नहीं खाती।'], [1, 'ठीक है, तो पहले उन दो इनवॉइस को ठीक करवाते हैं।'], [3, 'मैं शुक्रवार तक सप्लायर से सही इनवॉइस मँगवा लूँगी।'], [2, 'अगले महीने के लिए हमें चार हज़ार बोल्ट और चाहिए।'], [1, 'तो तय रहा, ऑर्डर इसी हफ्ते भेज देंगे।'], [1, 'धन्यवाद, आज के लिए इतना ही।']];
