    add(c2, 11, 'Vikram Joshi', 'vikram.j@example.com', 'Pune', 'Procurement Analyst', '5 years in sourcing for an auto parts maker.', ['2021-2026 Procurement Analyst, Bharat Forge Components (Pune)'], ['B.Com, Symbiosis, 2020'], 'sap, excel, vendor management, negotiation, gst');
    add(c2, 10, 'Sneha Pillai', 'sneha.p@example.com', 'Chennai', 'Senior Buyer', '8 years buying castings and fasteners. Built supplier scorecards in Power BI.', ['2018-2026 Senior Buyer, TVS Supply (Chennai)'], ['MBA Operations, LIBA, 2018'], 'sap, power bi, vendor management, negotiation, logistics');
    add(c2, 9, 'Karan Malhotra', 'karan.m@example.com', 'Delhi', 'Accounts Executive', '3 years in accounts payable.', ['2023-2026 Accounts Executive, Northline Traders (Delhi)'], ['B.Com, Delhi University, 2022'], 'tally, gst, excel');
